customize.css:
.wrap{max-width:80rem;padding:0 2rem 3rem}
header.site{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:1rem 1.5rem;min-height:5.5rem;margin:0 0 2rem;padding:1rem 0;border-bottom:1px solid var(--rule);font:700 .9rem/1.25 system-ui,sans-serif}
header.site .brand{color:var(--fg);font-size:1.25rem;font-weight:800;letter-spacing:.01em;text-decoration:none}
header.site nav{display:flex;align-items:center;flex-wrap:wrap;gap:.4rem 1.1rem}
header.site nav a{margin:0;color:var(--fg);font-size:.85rem;font-weight:700;letter-spacing:.025em;text-decoration:none;text-transform:uppercase}
header.site nav a:hover{color:var(--link)}
header.site nav a:nth-last-child(2),header.site nav a:nth-last-child(3){padding:.55rem .85rem;border:2px solid var(--link);color:var(--link)}
header.site nav a:nth-last-child(2):hover,header.site nav a:nth-last-child(3):hover{background:var(--link);color:var(--bg)}
header.site nav a:last-child{color:var(--muted);font-size:.75rem;font-weight:500;text-transform:none}
section.home{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:1.25rem 1.5rem;align-items:center}
section.home>p:nth-child(2){grid-column:1/4;grid-row:2/span 3;margin:0}
section.home>h2:nth-child(3){grid-column:4/7;grid-row:2;margin:0}
section.home>p:nth-child(4){grid-column:4/7;grid-row:3}
section.home>p:nth-child(5){grid-column:4/7;grid-row:4}
section.home>h2:nth-child(6){grid-column:1/4;grid-row:5;margin:0}
section.home>p:nth-child(7){grid-column:1/4;grid-row:6}
section.home>p:nth-child(8){grid-column:1/4;grid-row:7}
section.home>p:nth-child(9){grid-column:4/7;grid-row:5/span 3;margin:0}
section.home>p:nth-child(2) img,section.home>p:nth-child(9) img{display:block;width:100%;height:100%;max-height:30rem;object-fit:cover}
section.home>h2:nth-child(10){grid-column:1/7;grid-row:8;margin:2.5rem 0 .5rem}
section.home>h3:nth-child(11){grid-column:1/3;grid-row:9}
section.home>p:nth-child(12){grid-column:1/3;grid-row:10}
section.home>h3:nth-child(13){grid-column:3/5;grid-row:9}
section.home>p:nth-child(14){grid-column:3/5;grid-row:10}
section.home>h3:nth-child(15){grid-column:5/7;grid-row:9}
section.home>p:nth-child(16){grid-column:5/7;grid-row:10}
section.home>h2:nth-child(17){grid-column:1/7;grid-row:11;margin:2.5rem 0 .5rem}
section.home>p:nth-child(18){grid-column:1/4;grid-row:12}
section.home>p:nth-child(19){grid-column:4/7;grid-row:12}
section.home>p:nth-child(5) a,section.home>p:nth-child(8) a,section.home>p:nth-child(19) a{display:inline-block;padding:.65rem 1rem;border:2px solid var(--link);color:var(--link);font-weight:700;text-decoration:none}
section.home>p:nth-child(5) a:hover,section.home>p:nth-child(8) a:hover,section.home>p:nth-child(19) a:hover{background:var(--link);color:var(--bg)}
h1,h2,h3,h4{font-family:var(--heading-font)}
h1{font-size:clamp(2rem,4.5vw,3.5rem);line-height:1.12}
h2{font-size:clamp(1.5rem,2.6vw,2.1rem);line-height:1.2}
h3{font-size:1.25rem;line-height:1.3}
footer.site{margin-top:4rem;padding:1.5rem 0;border-top:1px solid var(--rule);font:.9rem/1.6 system-ui,sans-serif}
@media(max-width:700px){.wrap{padding:0 1rem 2.5rem}header.site{align-items:flex-start;gap:1rem}header.site nav{gap:.45rem .8rem}header.site nav a{font-size:.75rem}header.site nav a:nth-last-child(2),header.site nav a:nth-last-child(3){padding:.4rem .6rem}section.home{display:block}section.home>p:nth-child(2) img,section.home>p:nth-child(9) img{height:auto;max-height:22rem}}
section.home>.webcli-slideshow{grid-column:1/-1;grid-row:1;margin:0 0 1.5rem}
section.home>h3{text-align:center}
section.home>h3::before{display:block;font-family:"Font Awesome 6 Free";font-style:normal;font-weight:900;font-size:2.75rem;line-height:1;color:#35aacf;margin:0 0 .75rem}
section.home>h3:nth-of-type(1)::before{content:"" / ""}
section.home>h3:nth-of-type(2)::before{content:"" / ""}
section.home>h3:nth-of-type(3)::before{content:"" / ""}
section.home>p:nth-child(12),section.home>p:nth-child(14),section.home>p:nth-child(16){text-align:center;align-self:start}
header.site nav a[href*="request-a-quote"]::after,header.site nav a[href^="https://shop.swim-platform.com"]::after{display:inline-block;font-family:"Font Awesome 6 Free";font-style:normal;font-weight:900;line-height:1;margin-left:.45em}
header.site nav a[href*="request-a-quote"]::after{content:"" / "";font-weight:400}
header.site nav a[href^="https://shop.swim-platform.com"]::after{content:"" / ""}
